import{_ as l,a0 as t,w as r,s as o,I as a,x as n,a1 as e,A as i,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"在 Linux 上以樹狀查看文件和進程 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上以樹狀查看文件和進程 | LCTT (201910) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上以樹狀查看文件和進程 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上以樹狀查看文件和進程 | LCTT (201910) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201910/20191010 Viewing files and processes as trees on Linux","title":"在 Linux 上以樹狀查看文件和進程","tag":"201910","desc":""},"relativePath":"201910/20191010 Viewing files and processes as trees on Linux.md","filePath":"[post].md"}'),c={name:"201910/20191010 Viewing files and processes as trees on Linux.md"};function h(u,s,g,k,b,f){const p=t("Link");return r(),o("div",null,[s[23]||(s[23]=a("h1",{id:"在-linux-上以樹狀查看文件和進程",tabindex:"-1"},[n("在 Linux 上以樹狀查看文件和進程 "),a("a",{class:"header-anchor",href:"#在-linux-上以樹狀查看文件和進程","aria-label":"Permalink to “在 Linux 上以樹狀查看文件和進程”"},"​")],-1)),s[24]||(s[24]=a("blockquote",null,[a("p",null,"介紹三個 Linux 命令：ps、pstree 和 tree 以類似樹的格式查看文件和進程。")],-1)),s[25]||(s[25]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/201910/15/093202rwm5k9pnpntgbtpr.jpg",alt:""})],-1)),a("p",null,[e(p,{href:"https://www.networkworld.com/article/3215226/what-is-linux-uses-featres-products-operating-systems.html"},{default:i(()=>[...s[0]||(s[0]=[n("Linux",-1)])]),_:1}),s[1]||(s[1]=n(" 提供了一些方便的命令，用於以樹狀分支形式查看文件和進程，從而易於查看它們之間的關係。在本文中，我們將介紹 ",-1)),s[2]||(s[2]=a("code",null,"ps",-1)),s[3]||(s[3]=n("、",-1)),s[4]||(s[4]=a("code",null,"pstree",-1)),s[5]||(s[5]=n(" 和 ",-1)),s[6]||(s[6]=a("code",null,"tree",-1)),s[7]||(s[7]=n(" 命令以及它們提供的一些選項，這些選項可幫助你將注意力集中在要查看的內容上。",-1))]),s[26]||(s[26]=d(`<h3 id="ps" tabindex="-1">ps <a class="header-anchor" href="#ps" aria-label="Permalink to “ps”">​</a></h3><p>我們用來列出進程的 <code>ps</code> 命令有一些有趣的選項，但是很多人從來沒有利用過。雖然常用的 <code>ps -ef</code> 提供了正在運行的進程的完整列表，但是 <code>ps -ejH</code> 命令增加了一個不錯的效果。它縮進了相關的進程以使這些進程之間的關係在視覺上更加清晰——就像這個片段：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ps -ejH</span></span>
<span class="line"><span>  PID  PGID   SID TTY          TIME CMD</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span> 1396  1396  1396 ?        00:00:00   sshd</span></span>
<span class="line"><span>28281 28281 28281 ?        00:00:00     sshd</span></span>
<span class="line"><span>28409 28281 28281 ?        00:00:00       sshd</span></span>
<span class="line"><span>28410 28410 28410 pts/0    00:00:00         bash</span></span>
<span class="line"><span>30968 30968 28410 pts/0    00:00:00           ps</span></span></code></pre></div><p>可以看到，正在運行的 <code>ps</code> 進程是在 <code>bash</code> 中運行的，而 <code>bash</code> 是在 ssh 會話中運行的。</p><p><code>-exjf</code> 選項字符串提供了類似的視圖，但是帶有一些其它細節和符號以突出顯示進程的層次結構性質：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ps -exjf</span></span>
<span class="line"><span>PPID   PID  PGID   SID TTY      TPGID STAT   UID   TIME COMMAND</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>    1  1396  1396  1396 ?           -1 Ss       0   0:00 /usr/sbin/sshd -D</span></span>
<span class="line"><span> 1396 28281 28281 28281 ?           -1 Ss       0   0:00  \\_ sshd: shs [priv]</span></span>
<span class="line"><span>28281 28409 28281 28281 ?           -1 S     1000   0:00      \\_ sshd: shs@pts/0</span></span>
<span class="line"><span>28409 28410 28410 28410 pts/0    31028 Ss    1000   0:00          \\_ -bash</span></span>
<span class="line"><span>28410 31028 31028 28410 pts/0    31028 R+    1000   0:00              \\_ ps axjf</span></span></code></pre></div><p>命令中使用的這些選項表示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>-e  選擇所有進程</span></span>
<span class="line"><span>-j  使用工作格式</span></span>
<span class="line"><span>-f  提供完整格式列表</span></span>
<span class="line"><span>-H  分層顯示進程（如，樹狀格式）</span></span>
<span class="line"><span>-x  取消“必須與 tty 相關聯”的限制</span></span></code></pre></div><p>同時，該命令也有一個 <code>--forest</code> 選項提供了類似的視圖。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ps -ef --forest</span></span>
<span class="line"><span>UID        PID  PPID  C STIME TTY          TIME CMD</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>root      1396     1  0 Oct08 ?        00:00:00 /usr/sbin/sshd -D</span></span>
<span class="line"><span>root     28281  1396  0 12:55 ?        00:00:00  \\_ sshd: shs [priv]</span></span>
<span class="line"><span>shs      28409 28281  0 12:56 ?        00:00:00      \\_ sshd: shs@pts/0</span></span>
<span class="line"><span>shs      28410 28409  0 12:56 pts/0    00:00:00          \\_ -bash</span></span>
<span class="line"><span>shs      32351 28410  0 14:39 pts/0    00:00:00              \\_ ps -ef --forest</span></span></code></pre></div><p>注意，這些示例只是這些命令如何使用的示例。你可以選擇最適合你的進程視圖的任何選項組合。</p><h3 id="pstree" tabindex="-1">pstree <a class="header-anchor" href="#pstree" aria-label="Permalink to “pstree”">​</a></h3><p>使用 <code>pstree</code> 命令可以獲得類似的進程視圖。儘管 <code>pstree</code> 具備了許多選項，但是該命令本身就提供了非常有用的顯示。注意，許多父子進程關係顯示在單行而不是後續行上。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pstree</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>        ├─sshd───sshd───sshd───bash───pstree</span></span>
<span class="line"><span>        ├─systemd─┬─(sd-pam)</span></span>
<span class="line"><span>        │         ├─at-spi-bus-laun─┬─dbus-daemon</span></span>
<span class="line"><span>        │         │                 └─3*[{at-spi-bus-laun}]</span></span>
<span class="line"><span>        │         ├─at-spi2-registr───2*[{at-spi2-registr}]</span></span>
<span class="line"><span>        │         ├─dbus-daemon</span></span>
<span class="line"><span>        │         ├─ibus-portal───2*[{ibus-portal}]</span></span>
<span class="line"><span>        │         ├─pulseaudio───2*[{pulseaudio}]</span></span>
<span class="line"><span>        │         └─xdg-permission-───2*[{xdg-permission-}]</span></span></code></pre></div><p>通過 <code>-n</code> 選項，<code>pstree</code> 以數值（按進程 ID）順序顯示進程：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pstree -n</span></span>
<span class="line"><span>systemd─┬─systemd-journal</span></span>
<span class="line"><span>        ├─systemd-udevd</span></span>
<span class="line"><span>        ├─systemd-timesyn───{systemd-timesyn}</span></span>
<span class="line"><span>        ├─systemd-resolve</span></span>
<span class="line"><span>        ├─systemd-logind</span></span>
<span class="line"><span>        ├─dbus-daemon</span></span>
<span class="line"><span>        ├─atopacctd</span></span>
<span class="line"><span>        ├─irqbalance───{irqbalance}</span></span>
<span class="line"><span>        ├─accounts-daemon───2*[{accounts-daemon}]</span></span>
<span class="line"><span>        ├─acpid</span></span>
<span class="line"><span>        ├─rsyslogd───3*[{rsyslogd}]</span></span>
<span class="line"><span>        ├─freshclam</span></span>
<span class="line"><span>        ├─udisksd───4*[{udisksd}]</span></span>
<span class="line"><span>        ├─networkd-dispat</span></span>
<span class="line"><span>        ├─ModemManager───2*[{ModemManager}]</span></span>
<span class="line"><span>        ├─snapd───10*[{snapd}]</span></span>
<span class="line"><span>        ├─avahi-daemon───avahi-daemon</span></span>
<span class="line"><span>        ├─NetworkManager───2*[{NetworkManager}]</span></span>
<span class="line"><span>        ├─wpa_supplicant</span></span>
<span class="line"><span>        ├─cron</span></span>
<span class="line"><span>        ├─atd</span></span>
<span class="line"><span>        ├─polkitd───2*[{polkitd}]</span></span>
<span class="line"><span>        ├─colord───2*[{colord}]</span></span>
<span class="line"><span>        ├─unattended-upgr───{unattended-upgr}</span></span>
<span class="line"><span>        ├─sshd───sshd───sshd───bash───pstree</span></span></code></pre></div><p>使用 <code>pstree</code> 時可以考慮的一些選項包括 <code>-a</code>（包括命令列參數）和 <code>-g</code>（包括進程組）。</p><p>以下是一些簡單的示例（片段）。</p><p>命令 <code>pstree -a</code> 的輸出內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>└─wpa_supplicant -u -s -O /run/wpa_supplicant</span></span></code></pre></div><p>命令 <code>pstree -g</code> 的輸出內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>├─sshd(1396)───sshd(28281)───sshd(28281)───bash(28410)───pstree(1115)</span></span></code></pre></div><h3 id="tree" tabindex="-1">tree <a class="header-anchor" href="#tree" aria-label="Permalink to “tree”">​</a></h3><p>雖然 <code>tree</code> 命令聽起來與 <code>pstree</code> 非常相似，但這是用於查看文件而非進程的命令。它提供了一個漂亮的樹狀目錄和文件視圖。</p><p>如果你使用 <code>tree</code> 命令查看 <code>/proc</code> 目錄，你顯示的開頭部分將類似於這個：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tree /proc</span></span>
<span class="line"><span>/proc</span></span>
<span class="line"><span>├── 1</span></span>
<span class="line"><span>│   ├── attr</span></span>
<span class="line"><span>│   │   ├── apparmor</span></span>
<span class="line"><span>│   │   │   ├── current</span></span>
<span class="line"><span>│   │   │   ├── exec</span></span>
<span class="line"><span>│   │   │   └── prev</span></span>
<span class="line"><span>│   │   ├── current</span></span>
<span class="line"><span>│   │   ├── display</span></span>
<span class="line"><span>│   │   ├── exec</span></span>
<span class="line"><span>│   │   ├── fscreate</span></span>
<span class="line"><span>│   │   ├── keycreate</span></span>
<span class="line"><span>│   │   ├── prev</span></span>
<span class="line"><span>│   │   ├── smack</span></span>
<span class="line"><span>│   │   │   └── current</span></span>
<span class="line"><span>│   │   └── sockcreate</span></span>
<span class="line"><span>│   ├── autogroup</span></span>
<span class="line"><span>│   ├── auxv</span></span>
<span class="line"><span>│   ├── cgroup</span></span>
<span class="line"><span>│   ├── clear_refs</span></span>
<span class="line"><span>│   ├── cmdline</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>如果以 root 權限運行這條命令（<code>sudo tree /proc</code>），你將會看到更多詳細信息，因為 <code>/proc</code> 目錄的許多內容對於普通用户而言是無法訪問的。</p><p>命令 <code>tree -d</code> 將會限制僅顯示目錄。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tree -d /proc</span></span>
<span class="line"><span>/proc</span></span>
<span class="line"><span>├── 1</span></span>
<span class="line"><span>│   ├── attr</span></span>
<span class="line"><span>│   │   ├── apparmor</span></span>
<span class="line"><span>│   │   └── smack</span></span>
<span class="line"><span>│   ├── fd [error opening dir]</span></span>
<span class="line"><span>│   ├── fdinfo [error opening dir]</span></span>
<span class="line"><span>│   ├── map_files [error opening dir]</span></span>
<span class="line"><span>│   ├── net</span></span>
<span class="line"><span>│   │   ├── dev_snmp6</span></span>
<span class="line"><span>│   │   ├── netfilter</span></span>
<span class="line"><span>│   │   └── stat</span></span>
<span class="line"><span>│   ├── ns [error opening dir]</span></span>
<span class="line"><span>│   └── task</span></span>
<span class="line"><span>│       └── 1</span></span>
<span class="line"><span>│           ├── attr</span></span>
<span class="line"><span>│           │   ├── apparmor</span></span>
<span class="line"><span>│           │   └── smack</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>使用 <code>-f</code> 選項，<code>tree</code> 命令會顯示完整的路徑。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tree -f /proc</span></span>
<span class="line"><span>/proc</span></span>
<span class="line"><span>├── /proc/1</span></span>
<span class="line"><span>│   ├── /proc/1/attr</span></span>
<span class="line"><span>│   │   ├── /proc/1/attr/apparmor</span></span>
<span class="line"><span>│   │   │   ├── /proc/1/attr/apparmor/current</span></span>
<span class="line"><span>│   │   │   ├── /proc/1/attr/apparmor/exec</span></span>
<span class="line"><span>│   │   │   └── /proc/1/attr/apparmor/prev</span></span>
<span class="line"><span>│   │   ├── /proc/1/attr/current</span></span>
<span class="line"><span>│   │   ├── /proc/1/attr/display</span></span>
<span class="line"><span>│   │   ├── /proc/1/attr/exec</span></span>
<span class="line"><span>│   │   ├── /proc/1/attr/fscreate</span></span>
<span class="line"><span>│   │   ├── /proc/1/attr/keycreate</span></span>
<span class="line"><span>│   │   ├── /proc/1/attr/prev</span></span>
<span class="line"><span>│   │   ├── /proc/1/attr/smack</span></span>
<span class="line"><span>│   │   │   └── /proc/1/attr/smack/current</span></span>
<span class="line"><span>│   │   └── /proc/1/attr/sockcreate</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>分層顯示通常可以使進程和文件之間的關係更容易理解。可用選項的數量很多，而你總可以找到一些視圖，幫助你查看所需的內容。</p><hr>`,33)),a("p",null,[s[9]||(s[9]=n("via: ",-1)),e(p,{href:"https://www.networkworld.com/article/3444589/viewing-files-and-processes-as-trees-on-linux.html"},{default:i(()=>[...s[8]||(s[8]=[n("https://www.networkworld.com/article/3444589/viewing-files-and-processes-as-trees-on-linux.html",-1)])]),_:1})]),a("p",null,[s[14]||(s[14]=n("作者：",-1)),e(p,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...s[10]||(s[10]=[n("Sandra Henry-Stocker",-1)])]),_:1}),s[15]||(s[15]=n(" 選題：",-1)),e(p,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[11]||(s[11]=[n("lujun9972",-1)])]),_:1}),s[16]||(s[16]=n(" 譯者：",-1)),e(p,{href:"https://github.com/laingke"},{default:i(()=>[...s[12]||(s[12]=[n("laingke",-1)])]),_:1}),s[17]||(s[17]=n(" 校對：",-1)),e(p,{href:"https://github.com/wxy"},{default:i(()=>[...s[13]||(s[13]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[20]||(s[20]=n("本文由 ",-1)),e(p,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[18]||(s[18]=[n("LCTT",-1)])]),_:1}),s[21]||(s[21]=n(" 原創編譯，",-1)),e(p,{href:"https://linux.cn/"},{default:i(()=>[...s[19]||(s[19]=[n("Linux中國",-1)])]),_:1}),s[22]||(s[22]=n(" 榮譽推出",-1))])])}const C=l(c,[["render",h]]);export{y as __pageData,C as default};
